func (v ToolValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var inputSchema basetypes.ObjectValue

	if v.InputSchema.IsNull() {
		inputSchema = types.ObjectNull(
			InputSchemaValue{}.AttributeTypes(ctx),
		)
	}

	if v.InputSchema.IsUnknown() {
		inputSchema = types.ObjectUnknown(
			InputSchemaValue{}.AttributeTypes(ctx),
		)
	}

	if !v.InputSchema.IsNull() && !v.InputSchema.IsUnknown() {
		inputSchema = types.ObjectValueMust(
			InputSchemaValue{}.AttributeTypes(ctx),
			v.InputSchema.Attributes(),
		)
	}

	var outputSchema basetypes.ObjectValue

	if v.OutputSchema.IsNull() {
		outputSchema = types.ObjectNull(
			OutputSchemaValue{}.AttributeTypes(ctx),
		)
	}

	if v.OutputSchema.IsUnknown() {
		outputSchema = types.ObjectUnknown(
			OutputSchemaValue{}.AttributeTypes(ctx),
		)
	}

	if !v.OutputSchema.IsNull() && !v.OutputSchema.IsUnknown() {
		outputSchema = types.ObjectValueMust(
			OutputSchemaValue{}.AttributeTypes(ctx),
			v.OutputSchema.Attributes(),
		)
	}

	attributeTypes := map[string]attr.Type{
		"category":          basetypes.StringType{},
		"created_at":        basetypes.StringType{},
		"description":       basetypes.StringType{},
		"edge_function_url": basetypes.StringType{},
		"input_schema": basetypes.ObjectType{
			AttrTypes: InputSchemaValue{}.AttributeTypes(ctx),
		},
		"is_async": basetypes.BoolType{},
		"name":     basetypes.StringType{},
		"output_schema": basetypes.ObjectType{
			AttrTypes: OutputSchemaValue{}.AttributeTypes(ctx),
		},
		"output_schema_description": basetypes.StringType{},
		"response_mode":             basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"category":                  v.Category,
			"created_at":                v.CreatedAt,
			"description":               v.Description,
			"edge_function_url":         v.EdgeFunctionUrl,
			"input_schema":              inputSchema,
			"is_async":                  v.IsAsync,
			"name":                      v.Name,
			"output_schema":             outputSchema,
			"output_schema_description": v.OutputSchemaDescription,
			"response_mode":             v.ResponseMode,
		})

	return objVal, diags
}

func (v ToolValue) Equal(o attr.Value) bool {
	other, ok := o.(ToolValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Category.Equal(other.Category) {
		return false
	}

	if !v.CreatedAt.Equal(other.CreatedAt) {
		return false
	}

	if !v.Description.Equal(other.Description) {
		return false
	}

	if !v.EdgeFunctionUrl.Equal(other.EdgeFunctionUrl) {
		return false
	}

	if !v.InputSchema.Equal(other.InputSchema) {
		return false
	}

	if !v.IsAsync.Equal(other.IsAsync) {
		return false
	}

	if !v.Name.Equal(other.Name) {
		return false
	}

	if !v.OutputSchema.Equal(other.OutputSchema) {
		return false
	}

	if !v.OutputSchemaDescription.Equal(other.OutputSchemaDescription) {
		return false
	}

	if !v.ResponseMode.Equal(other.ResponseMode) {
		return false
	}

	return true
}

